INSERT INTO `schedule_rule` VALUES (1,'decision_variable','时间粒度','time_granularity','排程最小时间单位，单位为分钟','{\"unit\": \"分钟\", \"value\": 30, \"options\": [15, 30, 60]}',1,1,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(2,'decision_variable','规划窗口','planning_horizon','从当前时刻起向前规划的时长','{\"unit\": \"天\", \"value\": 90, \"options\": [30, 60, 90, 120]}',1,2,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(3,'constraint','能力匹配','capability_matching','任务指定的仪器或能力标签必须与候选仪器匹配','{\"strict\": true}',1,10,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(4,'constraint','维护窗口避让','maintenance_avoidance','任务的有效作业时间必须避开仪器计划维护时段','{\"strict\": true}',1,11,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(5,'constraint','项目时间窗','project_window','任务必须安排在所属项目的开始与结束时间范围内','{\"strict\": true}',1,12,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(6,'constraint','冻结期限制','freezing','非紧急任务不得进入冻结期，已冻结任务保持原排程不变','{\"strict\": true, \"freeze_days\": 1}',1,13,'2026-07-21 15:21:41','2026-07-30 09:24:33'),(7,'constraint','有效工作时段','working_hours','任务仅累计每日有效工作时段内的作业时间','{\"strict\": true, \"day_end\": \"20:00\", \"day_start\": \"08:30\", \"include_holidays\": false, \"include_weekends\": false}',1,14,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(8,'constraint','仪器唯一分配','instrument_assignment','每个需要仪器的任务必须分配到恰好一台兼容仪器','{\"locked\": true, \"strict\": true}',1,15,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(9,'constraint','仪器不重叠','non_overlap','同一台仪器上的任务及已冻结时段不能相互重叠','{\"strict\": true}',1,16,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(10,'constraint','跨项目切换间隔','cross_project_setup','同一仪器切换到不同项目时必须预留准备时间','{\"strict\": true, \"setup_hours\": 0.5}',1,17,'2026-07-21 15:21:41','2026-08-06 13:03:31'),(11,'constraint','前置依赖','precedence','任务必须在全部前置任务完成后才能开始','{\"strict\": true}',1,18,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(12,'constraint','里程碑期限','milestone_deadline','记录任务超过里程碑期限的延迟量，并由目标函数进行惩罚','{\"strict\": false}',1,19,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(13,'constraint','同级子任务靠拢','sibling_task_cohesion','同一父任务的同级子任务尽量提前完成，减少后续任务等待最晚子任务的时间','{\"strict\": false, \"weight\": 1.0}',1,20,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(14,'objective','最小化加权延迟','weighted_tardiness','主目标：优先保证高优先级任务按时完成','{\"weight\": 1.0, \"enabled\": true}',1,30,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(15,'objective','最小化最大完工时间','makespan','次目标：压缩整体排程周期，提高仪器周转效率','{\"weight\": 0.3, \"enabled\": true}',1,31,'2026-07-21 15:21:41','2026-07-21 15:21:41'),(16,'objective','最小化切换代价','switchover_cost_obj','次目标：减少同一仪器上的跨项目切换次数','{\"weight\": 0.2, \"enabled\": true}',1,32,'2026-07-21 15:21:41','2026-07-21 15:21:41');
