--
-- Table structure for table `sys_calendar`
--

DROP TABLE IF EXISTS `sys_calendar`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_calendar` (
  `id` int NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL COMMENT '日期',
  `is_working_day` tinyint(1) DEFAULT NULL COMMENT '是否工作日',
  `holiday_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '假期名称（如：春节、国庆节）',
  `day_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'workday/weekend/holiday/compensate',
  `source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'default/sync/manual',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `date` (`date`)
) ENGINE=InnoDB AUTO_INCREMENT=731 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

