--
-- Table structure for table `task`
--

DROP TABLE IF EXISTS `task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task` (
  `id` int NOT NULL AUTO_INCREMENT,
  `project_id` int NOT NULL,
  `name` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requires_instrument` tinyint(1) DEFAULT NULL,
  `requires_human` tinyint(1) DEFAULT NULL,
  `est_duration_hours` float DEFAULT NULL,
  `switchover_hours` float DEFAULT NULL,
  `allow_split` tinyint(1) DEFAULT NULL,
  `allow_transfer` tinyint(1) DEFAULT NULL,
  `milestone_id` int DEFAULT NULL,
  `priority_weight` float DEFAULT NULL,
  `instrument_ids` json DEFAULT NULL COMMENT '可选仪器ID列表',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delay_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `schedule_dirty` tinyint(1) DEFAULT NULL,
  `parent_id` int DEFAULT NULL,
  `plan_order` int NOT NULL COMMENT '项目计划同级排序',
  `assignee_id` int DEFAULT NULL,
  `is_external_gate` tinyint(1) DEFAULT NULL,
  `gate_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expected_approval_at` datetime DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `approved_by` int DEFAULT NULL,
  `approval_note` text COLLATE utf8mb4_unicode_ci,
  `approval_schedule_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approval_schedule_message` text COLLATE utf8mb4_unicode_ci,
  `approval_preview_token` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approval_schedule_run_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approval_moved_tasks` int DEFAULT NULL,
  `earliest_start` datetime DEFAULT NULL,
  `latest_due` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `project_id` (`project_id`),
  KEY `milestone_id` (`milestone_id`),
  KEY `parent_id` (`parent_id`),
  KEY `assignee_id` (`assignee_id`),
  KEY `approved_by` (`approved_by`),
  CONSTRAINT `task_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `project` (`id`),
  CONSTRAINT `task_ibfk_2` FOREIGN KEY (`milestone_id`) REFERENCES `milestone` (`id`),
  CONSTRAINT `task_ibfk_3` FOREIGN KEY (`parent_id`) REFERENCES `task` (`id`),
  CONSTRAINT `task_ibfk_4` FOREIGN KEY (`assignee_id`) REFERENCES `user` (`id`),
  CONSTRAINT `task_ibfk_5` FOREIGN KEY (`approved_by`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=258 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

